      lab: {Urate: r.chance(0.3) ? [0.34, 0.4] : [0.48, 0.62], CRP: [30, 80], WCC: [10.5, 13], Cr: [90, 130], Gluc: [5.6, 7.4], TG: [2.2, 3.6]},
      prof: [[`${age}-year-old ${sex === 'M' ? 'man' : 'woman'}`, 1, sex === 'M' ? 'Men > 30.' : 'Post-menopausal women (oestrogen is uricosuric).'], ['BMI over 30, metabolic syndrome', 1, 'Obesity, metabolic syndrome, CKD.'], [trigger === 'tb' ? 'On TB treatment (pyrazinamide)' : trigger === 'thiazide' ? 'Started hydrochlorothiazide' : 'Beer and red meat at a braai', 1, trigger === 'tb' ? 'Pyrazinamide ↓ urate excretion (past paper).' : trigger === 'thiazide' ? 'Thiazides ↓ urate excretion.' : 'Alcohol (beer — purines) and purine-rich meat.'], ['Collects vinyl records', 0, '—']],
      hx: [['Onset', 'Woke me at 3 a.m.; worst within 12 hours.', 1], ['Previous', 'Something similar in the other toe last year — went away in a week.', 1, 'Self-limiting 7–10 days; recurrent.'], ['Fever / rigors', 'Feel warm, no shaking chills.', 1, 'Rigors → think septic.'], ['Trauma / injection', 'No injury, no injections into the joint.', 1], ['Medicines', trigger === 'tb' ? 'TB pills (4 in 1).' : trigger === 'thiazide' ? 'Blood-pressure water pill.' : 'Nothing.', 1], ['Stones', 'Passed a kidney stone once.', 0, 'Uric acid stones.']],
