  keyInv: ['ASP'], okInv: ['PANEL_URATE', 'PANEL_FBC', 'PANEL_CRP', 'PANEL_UE', 'XR', 'PANEL_GLUC', 'PANEL_LIPID', 'BC'],
  must: [{k: 'nsaid|colchicine|steroid', n: 'Acute: NSAID (+ PPI) or low-dose colchicine or steroid', why: 'Terminate the attack.'}],
